) AS (
  VALUES 
    (153::BIGINT, 'Súper amable y califica muy suave. Asigna muchos trabajos pequeños que se hacen en menos de 10 minutos. 100% recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'ce9388750213a62c65724799b49fe577c11da30cefd773118bd71a8939711d35'::TEXT, ARRAY[600]::BIGINT[]),
    (153::BIGINT, 'Es una excelente profesora. Siempre intenta ayudar a sus estudiantes en todo lo que está a su alcance y es muy estricta con la asistencia. Si tiene la intención de cambiarse de carrera, le recomiendo matricular con ella, ya que es una excelente opción para obtener una buena nota.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2026-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'a63dfc29bc2adb5bc96b932ba184aa25e6eab2875613dfb7d9275f55a743e1d2'::TEXT, ARRAY[1683]::BIGINT[]),
    (153::BIGINT, 'Es una profesora demasiado buena, explica muy claro. Los trabajos son fáciles y califica muy suave. No lo dude en llevar con ella. Siempre está anuente a ayudar y a brindar apoyo, las clases no son tan largas y son bastante dinámicas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-01-08T00:00:00+00:00'::TIMESTAMPTZ, '51e16dec8ca561ff34a15d76af16305a1797b506fb14e87d40b426cd2fb1c54a'::TEXT, ARRAY[600]::BIGINT[]),
    (153::BIGINT, 'Excelente profesora, si puede matricular con ella no lo dude. Da un ambiente genial en clase y en general se aprende bastante, es muy fácil pasar con ella, eso si, desde un inicio escoja bien unos 5 compañeros pues el trabajo final se puede hacer tedioso si no los escoge bien.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, '9093244a911576b8bb363e72df6037aab717614778a61990ba9f7bea88b73976'::TEXT, ARRAY[556]::BIGINT[]),
    (153::BIGINT, 'Es una profesora muy buena, aunque a la hora de calificar puede ser algo estricta, siempre busca que sus estudiantes aprendan, y le gusta resolver dudas. Nada más les recomiendo escoger bien a sus compañeros de trabajo porque deja un trabajo de investigación, y si escogen compañeros vagos sufrirán.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, '3d1701316a25b724de99aa81c774cde20ae06e848ddfe7c8e3d1d8772c567899'::TEXT, ARRAY[556]::BIGINT[]),
    (153::BIGINT, 'Es una excelente profesora, dentro y fuera del aula, siempre dispuesta a ayudar y transmite unas vibras muy bonitas cuando da las clases, sin duda la mejor opción :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, '5c2029b23f6819f30231e909fa12f9d396e938bc9e2749b1c8c89761b6abccd3'::TEXT, ARRAY[600]::BIGINT[]),
    (153::BIGINT, 'Demasiado buena profesora, accesible, muy linda como persona, el curso lo hace muy llevadero porque califica muy bien mientras cumpla con lo que pide, los trabajos son fáciles y cortos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'ff0dc21afb931ca026089b1c87dd32a8bde2940b2bf8c0c45ec4f616cbd6c02a'::TEXT, ARRAY[556]::BIGINT[]),
    (153::BIGINT, 'Súper buena nota, explica muy bien y crea un ambiente amigable en clase. Es amable, paciente y siempre está dispuesta a ayudar con lo que uno necesite. Califica suave, las tareas son manejables y la materia se pasa fácilmente. Solo hay que estar pendiente de las notas , aveces se le van los puntos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, '4ed7978689fa572eff14fac0b97095841588df607a1c2532d5fdf7b533fdba52'::TEXT, ARRAY[556]::BIGINT[]),
    (153::BIGINT, 'Lleven cualquier curso con ella, es un amor y hace que la clase sea un ambiente muy amigable, califica suave y las tareas son bastante sencillas. Muy recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2025-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c8c8fa0e86e1dc9bb8853825c5dce962aaf38fe941080693bc77199291a7f29e'::TEXT, ARRAY[556]::BIGINT[]),
    (153::BIGINT, 'Profe super amable y buena el curso deporsi es fácil, ella es comprensiva pero eso si deja varias tareas algunas un pocos largas pero nada del otro mundo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, '4051717de089af74098ad5c8c462c5f55a4f1f06ad82225a19f7240c776bd03f'::TEXT, ARRAY[556]::BIGINT[]),
    (153::BIGINT, 'La profe es buena , amable. Mi único comentario es estar atento a las notas ya que a veces se le van puntillos . Pero muy buena profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '8b58dc571fae3fb5d25f6fb85143a59fa653d7d8cc67ff1135606569372b4f9c'::TEXT, ARRAY[555]::BIGINT[]),
    (153::BIGINT, 'Explica bien, es un amor de persona y lo ayuda con lo que uno necesite.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd3144a336ed7ea7b7b7963d0631707ba8a2c8166ba64af16ffc257664050025f'::TEXT, ARRAY[554]::BIGINT[]),
    (153::BIGINT, 'La profe es súper buena nota, lo trata a uno inclusive con cariño, se pasa muy fácilmente con ella, nada más que no haga que yo y se le olvide alguna de las tareas. La recomendaría muchísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'c4645f3d3b329cbbf849e60b420e2b7a531fc9fde3095a41ef1770e3309e5182'::TEXT, ARRAY[554]::BIGINT[]),
    (153::BIGINT, 'La profe es un amor de persona, hace que las clases sean bonitas y uno las disfrute porque tiene una energía demasiado linda, si puede meter con ella definitivamente hágalo, también se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-03-13T00:00:00+00:00'::TIMESTAMPTZ, 'aea1f62b11979f7028daebf6d4b4262ce46dd49fa610a108c045f34f4eea32f9'::TEXT, ARRAY[554, 600]::BIGINT[]),
    (153::BIGINT, 'Excelente profesora, tiene toda la vocación en su campo, siempre dispuesta a ayudar a los alumnos y entiende el rol del curso adecuadamente, totalmente recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-01-11T00:00:00+00:00'::TIMESTAMPTZ, '1e68f6a33ad31cbc0c09f5cabbdb27eed14c41ac46dbadbad2e0abdb79d623f8'::TEXT, ARRAY[600]::BIGINT[]),
    (153::BIGINT, 'La profe hace las clases super dinamicas y los examenes son realmente muy faciles, un amor de persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-15T00:00:00+00:00'::TIMESTAMPTZ, '8bf10fc9f64e4e1df5e84a86fb3561323db960990952b36d7bb402b43def64e8'::TEXT, ARRAY[600]::BIGINT[]),
    (153::BIGINT, 'Con solo matrícular con Saray ya pasó el curso, las clases son divertidas y los trabajos son easy, hay 2 examenes orales (uno individual y otro grupal) , que se hacen de una manera sencilla, normalmente le va a poner arriba de 90 en todo, excelente profesora y excelente persona, lleve con ella!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '1d1c34fd08c20cf99b834873fd7ad30448919fde14d00066fa9419212c1b5845'::TEXT, ARRAY[600]::BIGINT[]),
    (153::BIGINT, 'Es probablemente la mejor profe de Comunicación Oral. Es muy buena persona y es bastante tranquila. Las actividades que hace son interesantes. Deja trabajos seguido pero son muy sencillos. En las presentaciones casi siempre pone 100, o una nota muy alta, es muy fácil pasar con ella. Muy recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'fcb281ca4ce2abaee1a0d10a81ad1246976422293a424f88e7c497501a3f3988'::TEXT, ARRAY[600]::BIGINT[]),
    (153::BIGINT, 'Es fácil la mejor profe. Súper atenta y dispuesta a ayudar. No duden en matricular con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'b313ddb60fb0e20b619caed43e26d07215de6a0e8a47755fdcae60765d55448d'::TEXT, ARRAY[554]::BIGINT[]),
    (153::BIGINT, 'Recomiendo mucho a esta profe, ella comprende a los estudiantes y hace que la carga sea menos ligera aunque si deja bastantes trabajos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '63aaad47ecbf015f68d7ee839c905e96ee1264968f1711ff45a215cd6244e9fd'::TEXT, ARRAY[554]::BIGINT[]),
    (153::BIGINT, 'La mejor profesora que he conocido de comunicación escrita, es una muy buena persona, muy atenta, siempre responde dudas y hay muchos medios para comunicarse con ella. Hay tareas todas las semanas, pero son relativamente fáciles, al final del curso hay un proyecto grupal y un ensayo individual.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '16387b8251dfdf6ad3d4bb00e650cd913cfc99314adc30d9efab126ca1aac471'::TEXT, ARRAY[554]::BIGINT[]),
    (153::BIGINT, 'Es la mejor profesora, se los juro. Si matriculan con ella no se van a arrepentir.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'c26cfab70113e427631d7ea98d577a4ab8749bdc9475baedf2ff421faa9a4f67'::TEXT, ARRAY[554]::BIGINT[]),
    (153::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2022-11-28T00:00:00+00:00'::TIMESTAMPTZ, '517c3c259b9fa5239d857ac80f25fc28f8f34198437c8577b2a6ffb01a288a09'::TEXT, ARRAY[600]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
